contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, bool freeze) public {
        require(target != address(0), "target must be nonzero");

        // Check who the owner is as observed through the public getter
        address ownerBefore = c.owner();
        require(ownerBefore != address(this), "this must not be the owner to test non-owner revert");

        // Record the frozen state of target before the call
        bool frozenBefore = c.frozenAccount(target);

        // Attempt the owner-only call as a non-owner
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The call must revert because the caller is not the owner,
        // and the frozen state must remain unchanged.
        assert(reverted && c.frozenAccount(target) == frozenBefore);
    }
}

